const c = $('Config').first().json;
const day = 86400000;
const toDate = s => new Date(s + 'T00:00:00Z');
const asOf = toDate(c.asOfDate);

function parseCsv(text) {
  const rows = []; let row = [], cur = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (q) { if (ch === '"' && text[i + 1] === '"') { cur += '"'; i++; } else if (ch === '"') q = false; else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === ',') { row.push(cur); cur = ''; }
    else if (ch === '\n') { row.push(cur); rows.push(row); row = []; cur = ''; }
    else if (ch !== '\r') cur += ch;
  }
  if (cur || row.length) { row.push(cur); rows.push(row); }
  const [head, ...body] = rows;
  return body.filter(r => r.length > 1).map(r => Object.fromEntries(head.map((h, i) => [h.trim(), (r[i] || '').trim()])));
}

const files = {};
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  files[items[i].binary.data.fileName] = buf.toString('utf8');
}

const tasks = parseCsv(files['sample_task_board.csv']);
const timeline = parseCsv(files['project_timeline.csv']);
const risks = parseCsv(files['project_risks.csv']);

for (const t of tasks) {
  t.days_to_due = Math.round((toDate(t.due_date) - asOf) / day);
  t.flag = t.status === 'Blocked' ? 'Blocked'
    : t.status === 'Done' ? ''
    : t.days_to_due < 0 ? 'Overdue'
    : (t.status === 'To Do' && t.days_to_due <= c.atRiskDays) ? 'At risk'
    : (t.status === 'In Progress' && t.days_to_due <= c.watchDays) ? 'Watch' : '';
}

const labels = { 1: ['Planning'], 2: ['Analysis'], 3: ['Use Cases'], 4: ['Data Prep', 'Model Dev'], 5: ['Pilot'], 6: ['Evaluation'], 7: ['Deployment'], 8: ['Monitoring'] };
const phases = timeline.map(p => {
  const due = tasks.filter(t => labels[p.phase].includes(t.labels)).map(t => t.due_date).sort().at(-1);
  const ms = (toDate(due) - asOf) / day;
  return { phase: Number(p.phase), name: p.phase_name, weeks: p.start_week + '-' + p.end_week, activities: p.key_activities, milestones: p.milestones_deliverables, end_date: due, in_window: ms > 0 && ms <= c.milestoneDays };
});

return [{ json: { asOfDate: c.asOfDate, description: files['project_description.txt'], phases, risks, tasks } }];

const c = $('Config').first().json;
const system = `You route requests for Mira, a project assistant for the ABCDE Ltd. AI Adoption Project. Return only JSON with the keys intent, sufficient_detail, sprint, top_n, format, focus.
intent: plan (project plans), risk (risk assessments or top risks), status (weekly status reports, task counts, progress summaries or sprint update emails), milestones (blocked, at-risk or overdue tasks, deadlines, or upcoming milestones), other (anything else).
sufficient_detail: Always true when the request mentions the ABCDE Ltd. project, the AI Adoption Project, the provided project description, the task board, the timeline, the risk data or a sprint. Mira always has the ABCDE Ltd. AI Adoption Project files loaded (description, timeline, risks, task board). Set true when the request asks about that project or anything those files answer: its plan, risks, tasks, sprints, blocked or overdue items, task counts, milestones, status or updates. Set false when the request is about a new or unnamed project with no details, for example 'Plan a new mobile app', 'Assess risks for my upcoming project' or 'Plan a 3-week project, no other details', or when it states its own opinion in place of data, for example 'Write a status report: everything is fine'.
sprint: the sprint number if named, else null. top_n: the number if the request asks for the top N risks, else null.
format (status only): report for a weekly status report, summary for task counts, email for an update email. focus (milestones only): blocked_at_risk for blocked or at-risk tasks, upcoming_milestones for milestones coming up. Use null for format unless intent is status, and null for focus unless intent is milestones.`;
return [{ json: { model: c.model, system, user: c.request, jsonMode: true, t0: Date.now() } }];

let r;
try { r = JSON.parse($json.text); } catch (e) { r = { intent: 'other', sufficient_detail: false }; }
if (r.focus) r.intent = 'milestones';
const ok = r.sufficient_detail === true && ['plan', 'risk', 'status', 'milestones'].includes(r.intent);
return [{ json: { ...r, route: ok ? r.intent : 'clarify' } }];

const p = $('Parse intent').first().json;
const ask = {
  plan: 'To build a plan I need: the project scope, the goals, the deliverables, the timeline and the team size.',
  risk: 'To assess risks I need: the project description or scope, the timeline, the domain or technology, and the team or stakeholders.',
  status: 'No task data is available for this request, so I cannot report status. Please share the task board export (CSV) or a task list with statuses.',
  milestones: 'No timeline or task data is available for this request. Please share the project timeline or task board.',
};
const text = 'This request does not have enough detail. ' + (ask[p.intent] || 'Please tell me which project and which output you need (a plan, a risk assessment or a status report), and share the scope, goals, deliverables, timeline and team size.');
return [{ json: { text } }];

const f = $('Data Loader').first().json;
const p = $('Parse intent').first().json;
const tasks = p.sprint ? f.tasks.filter(t => t.sprint === 'Sprint ' + p.sprint) : f.tasks;
const counts = { Done: 0, 'In Progress': 0, 'To Do': 0, Blocked: 0 };
for (const t of tasks) counts[t.status] = (counts[t.status] || 0) + 1;
const countsLine = 'Done ' + counts.Done + ', In Progress ' + counts['In Progress'] + ', To Do ' + counts['To Do'] + ', Blocked ' + counts.Blocked + ', Total ' + tasks.length;
return [{ json: { scope: p.sprint ? 'Sprint ' + p.sprint : 'All sprints', tasks, counts, countsLine, total: tasks.length, upcoming: f.phases.filter(x => x.in_window) } }];

