const p = $('Parse intent').first().json;
const c = $('Config').first().json;
const text = $json.text || '';
const refused = /^INSUFFICIENT DETAIL/i.test(text.trim());
const route = refused ? 'clarify' : p.route;
const output = refused ? 'This request does not have enough detail. ' + text.replace(/^INSUFFICIENT DETAIL:?\s*/i, 'Please provide: ')
  : route === 'clarify' ? text
  : text + `\n\nAs-of date: ${c.asOfDate}. Sources: project_description.txt, project_timeline.csv, project_risks.csv, sample_task_board.csv.`;
return [{ json: { output, route, requiresApproval: route !== 'clarify', model: $json.model, usage: $json.usage, latencyMs: $json.latencyMs } }];

const f = $json;
const c = $('Config').first().json;
const o = $('Orchestrator call').first().json;
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const ns = ms => String(Math.round(ms)) + '000000';
const str = (k, v) => ({ key: k, value: { stringValue: String(v) } });
const traceId = hex(32), rootId = hex(16);
const tags = { key: 'langfuse.trace.tags', value: { arrayValue: { values: [{ stringValue: c.testId || 'chat' }, { stringValue: c.model }] } } };
const shared = [str('langfuse.trace.name', 'mira-request'), tags, str('langfuse.trace.metadata.test_id', c.testId || ''), str('langfuse.trace.metadata.route', f.route), str('langfuse.trace.metadata.model', c.model), str('langfuse.trace.metadata.as_of_date', c.asOfDate)];
const span = (id, parent, name, start, stop, attrs) => ({ traceId, spanId: id, ...(parent ? { parentSpanId: parent } : {}), name, kind: 1, startTimeUnixNano: ns(start), endTimeUnixNano: ns(stop), attributes: [...shared, ...attrs] });
const gen = (call, input, output) => [str('langfuse.observation.type', 'generation'), str('langfuse.observation.model.name', call.model), str('langfuse.observation.input', input), str('langfuse.observation.output', output), str('langfuse.observation.usage_details', JSON.stringify({ input: call.usage.prompt_tokens, output: call.usage.completion_tokens, total: call.usage.total_tokens }))];
const end = Date.now(), start = Number(c.t0);
const branchStart = end - (f.latencyMs || 0);
const spans = [
  span(rootId, null, 'mira-request', start, end, [str('langfuse.observation.type', 'span'), str('langfuse.observation.input', c.request), str('langfuse.observation.output', f.output)]),
  span(hex(16), rootId, 'orchestrator', branchStart - o.latencyMs, branchStart, gen(o, c.request, $('Parse intent').first().json.route)),
];
if (f.usage) spans.push(span(hex(16), rootId, f.route, branchStart, end, gen(f, c.request, f.output)));
const payload = { resourceSpans: [{ resource: { attributes: [str('service.name', 'mira-n8n')] }, scopeSpans: [{ scope: { name: 'mira' }, spans }] }] };
return [{ json: { ...f, testId: c.testId, traceId, rootId, payload } }];
